// HasCatalogRevision applies the HasEdge predicate on the "catalog_revision" edge.
func HasCatalogRevision() predicate.OnboardingTraitOffer {
	return predicate.OnboardingTraitOffer(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, CatalogRevisionTable, CatalogRevisionColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasCatalogRevisionWith applies the HasEdge predicate on the "catalog_revision" edge with a given conditions (other predicates).
func HasCatalogRevisionWith(preds ...predicate.CultivationCatalogRevision) predicate.OnboardingTraitOffer {
	return predicate.OnboardingTraitOffer(func(s *sql.Selector) {
		step := newCatalogRevisionStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

