// And groups predicates with the AND operator between them.
func And(predicates ...predicate.OnboardingTraitOffer) predicate.OnboardingTraitOffer {
	return predicate.OnboardingTraitOffer(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
